(function(){'use strict';
/* Environmental Engineering Database generator — jahdb-environmental-engineering-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-ENVENG-';
var SRC='public';
var RECORD_KIND='environmental engineering record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Water Treatment Plant Design","brief":"Engineering the multi-barrier systems that turn raw rivers, lakes, and aquifers into safe drinking water.","points":["Design starts with source-water characterization — turbidity, organics, pathogens, and minerals.","Conventional trains: rapid mix, flocculation, sedimentation, filtration, disinfection.","Hydraulic design balances flow, detention time, and head loss across every unit process.","Redundancy and standby capacity keep water flowing during maintenance and emergencies."],"examples":["A 50-MGD plant's flocculation basins gently growing settleable floc.","A filter gallery's dual-media beds polishing water to crystal clarity."],"history":["Slow sand filters (1800s) gave way to rapid filtration and chlorination by the 1910s.","The 1974 Safe Drinking Water Act drove the modern treatment-plant building boom."],"uses":["Municipal utilities design plants for decades of population growth.","Engineers retrofit aging plants for new contaminants like PFAS.","Disaster-relief teams deploy package plants for emergency supply."],"qa":[["How big should a plant be?","Sized for 20-50-year demand forecasts plus fire flow and redundancy."],["What drives treatment choice?","Source-water quality — clean groundwater needs far less than muddy rivers."],["How long do plants last?","Structures 50-100 years; mechanical systems 20-30 with renewal."]]},{"title":"Wastewater Treatment Processes","brief":"The engineered biology and chemistry that cleans sewage — primary, secondary, and advanced treatment.","points":["Primary treatment settles solids; secondary uses microbes to digest dissolved pollutants.","Activated sludge, trickling filters, and MBRs each suit different flows and limits.","Disinfection (chlorine, UV, ozone) kills pathogens before discharge.","Biosolids handling — digestion, dewatering, disposal — is half the plant's work."],"examples":["An aeration basin's brown soup of hungry microbes digesting waste.","A UV channel's blue glow disinfecting effluent without chemicals."],"history":["London's 1860s sewers ended cholera; biological treatment matured in the 1910s-20s.","The 1972 Clean Water Act forced secondary treatment across America."],"uses":["Cities operate treatment plants under strict discharge permits.","Engineers upgrade plants for nutrient limits and energy recovery.","Decentralized systems serve towns too small for big plants."],"qa":[["What is BOD?","Biochemical oxygen demand — the pollution load microbes must digest."],["Do plants remove pharmaceuticals?","Partially — advanced processes do better; source control helps most."],["What happens to the solids?","Digested into biosolids, often land-applied as fertilizer."]]},{"title":"Air Pollution Control Devices","brief":"The hardware that strips particles and gases from industrial exhaust before it reaches the sky.","points":["Cyclones spin out coarse dust cheaply; baghouses filter fine particles at 99%+ efficiency.","Electrostatic precipitators charge particles and collect them on plates.","Scrubbers absorb gases like SO2 into liquid; SCR catalysts destroy NOx with ammonia.","Control choice follows particle size, gas chemistry, and temperature."],"examples":["A baghouse's rows of filter bags pulsing clean on a cement plant.","An SCR system cutting a power plant's NOx by 90 percent."],"history":["1970s Clean Air Act rules created the modern control-device industry.","The 1990 acid-rain program made scrubbers standard on coal plants."],"uses":["Engineers size controls to meet permit limits at least cost.","Inspectors verify performance with stack testing.","Retrofits keep aging plants compliant with tightening rules."],"qa":[["Which device for fine particles?","Baghouses or ESPs — both exceed 99% on PM2.5."],["Do controls hurt efficiency?","They add pressure drop and energy use — design minimizes the penalty."],["What about CO2?","Carbon capture is the emerging add-on for combustion sources."]]},{"title":"Solid Waste Management","brief":"The engineered system collecting, processing, and disposing of society's discards.","points":["Integrated hierarchy: reduce, reuse, recycle, recover energy, landfill last.","Collection routing and transfer stations dominate system cost.","Materials recovery facilities (MRFs) sort recyclables with screens, magnets, and optical sorters.","Planning balances cost, diversion goals, and environmental protection."],"examples":["A city's automated side-loaders running optimized collection routes.","An optical sorter flicking PET bottles off a MRF conveyor."],"history":["1970s sanitary landfills replaced open dumps; recycling curbside boomed in the 1990s.","The 2010s-20s brought organics diversion and waste-to-energy growth."],"uses":["Cities plan decades of disposal capacity and diversion programs.","Engineers design landfills, MRFs, and composting facilities.","Consultants audit waste streams to find diversion opportunities."],"qa":[["Is recycling worth it?","For metals, paper, and PET, emphatically yes — economics and energy both favor it."],["What is zero waste?","A goal of 90%+ diversion through redesign, reuse, and composting."],["Where does my trash go?","Usually a regional landfill engineered with liners and gas collection."]]},{"title":"Landfill Engineering","brief":"Designing lined, monitored mountains of waste that protect groundwater for generations.","points":["Composite liners — clay plus geomembrane — contain leachate.","Leachate collection pipes drain contaminated water to treatment.","Gas wells capture methane for energy or flaring.","Final caps seal the landfill; monitoring continues 30+ years after closure."],"examples":["A dozer spreading the day's waste over the working face.","A flare station burning off collected landfill gas."],"history":["1970s liner requirements ended the era of leaching dumps.","Subtitle D (1991) set national design standards for municipal landfills."],"uses":["Engineers design cells, liners, and gas systems for new landfills.","Operators manage daily cover, compaction, and leachate.","Closed landfills become parks, solar farms, and golf courses."],"qa":[["Do landfills leak?","Modern lined landfills with monitoring rarely do; old unlined ones often did."],["How long does waste last?","Organics decay in decades; plastics persist for centuries."],["Can I build on a closed landfill?","Light uses yes — settlement and gas require engineering controls."]]},{"title":"Hazardous Waste Treatment","brief":"Neutralizing, destroying, or stabilizing the most dangerous industrial wastes.","points":["Treatment standards require destroying organics and immobilizing metals.","Incineration and thermal desorption destroy organic contaminants at high heat.","Stabilization binds metals into cement-like matrices that won't leach.","Manifests track every drum from generator to final disposal."],"examples":["A rotary kiln incinerator destroying pesticide wastes at 2,000 F.","A stabilization plant mixing contaminated soil with reagents."],"history":["RCRA (1976) created cradle-to-grave hazardous waste control.","The 1984 land-disposal restrictions forced treatment before burial."],"uses":["Generators classify waste and ship to permitted treatment facilities.","Engineers design treatment trains for complex waste streams.","Emergency responders stabilize spill wastes for transport."],"qa":[["What makes waste hazardous?","Ignitability, corrosivity, reactivity, toxicity — or listed source."],["Can hazardous waste be recycled?","Yes — solvents, metals, and oils are commonly reclaimed."],["How is it transported?","Licensed haulers with manifests and placarded vehicles."]]},{"title":"Soil Remediation Technologies","brief":"Engineering the cleanup of contaminated soil — dig, treat in place, or let nature work.","points":["Excavation and disposal is fastest but costliest for large volumes.","Soil vapor extraction pulls volatile contaminants from the vadose zone.","Bioremediation feeds native microbes to digest petroleum and solvents.","Thermal treatment bakes out contaminants for the toughest sites."],"examples":["Vapor-extraction wells quietly cleaning a former gas station lot.","Biopiles steaming as microbes digest oily soil."],"history":["1980s Superfund dig-and-haul gave way to 1990s in-situ innovation.","The 2000s brought risk-based closures avoiding endless cleanup."],"uses":["Engineers select remedies balancing cost, time, and future land use.","Contractors implement and monitor cleanup systems for years.","Regulators approve closure when risks are controlled."],"qa":[["How long does cleanup take?","Months for excavation; years to decades for in-situ methods."],["Is bioremediation reliable?","For petroleum, very — microbes evolved to eat hydrocarbons."],["What is risk-based closure?","Leaving low-risk contamination managed in place with controls."]]},{"title":"Groundwater Remediation","brief":"Pumping, treating, and containing polluted aquifers — the slowest, most patient cleanup work.","points":["Pump-and-treat captures plumes and treats water above ground.","Permeable reactive barriers treat water passively as it flows through.","Air sparging and chemical oxidation destroy contaminants in place.","Monitored natural attenuation relies on dilution and biodegradation with verification."],"examples":["An iron reactive wall intercepting a solvent plume for 20 years.","Injection wells delivering oxidant that fizzes through contaminated zones."],"history":["1980s pump-and-treat optimism met 1990s reality — plumes persist for decades.","The 2000s embraced passive barriers and natural attenuation."],"uses":["Engineers model plumes and design capture systems.","Treatment vendors supply carbon, oxidation, and bioremediation systems.","Long-term monitoring proves remedies protect drinking water."],"qa":[["Can aquifers be fully cleaned?","Sometimes; often the goal is containing risk, not pristine restoration."],["Why does it take so long?","Contaminants hide in low-permeability zones and slowly diffuse out."],["Who monitors?","Responsible parties under regulatory oversight, often for decades."]]},{"title":"Drinking Water Distribution Systems","brief":"The pressurized pipe networks delivering safe water to every tap — and keeping it safe en route.","points":["Hydraulic modeling sizes pipes for peak demand plus fire flow.","Storage tanks balance pressure and provide emergency reserves.","Disinfectant residual must survive to the farthest tap.","Cross-connection control prevents backflow contamination."],"examples":["A water tower's gravity pressure feeding a town overnight.","A main-break crew isolating a segment without losing system pressure."],"history":["19th-century piped water ended waterborne epidemics in cities.","The 2000s brought smart metering and real-time pressure management."],"uses":["Utilities model, maintain, and replace aging pipe networks.","Engineers design extensions for growth and resilience.","Emergency planners stage interconnections for disasters."],"qa":[["Why do pipes break?","Age, corrosion, pressure transients, and soil movement."],["What is a boil-water advisory?","Issued when pressure loss may have let contaminants in."],["How old is the infrastructure?","Much US pipe is 50-100 years old — replacement is the industry's big bill."]]},{"title":"Sewer System Design","brief":"Gravity's plumbing — collecting wastewater reliably without backups or overflows.","points":["Sanitary sewers carry wastewater; storm sewers carry rain; combined systems carry both.","Pipes slope to maintain self-cleansing velocity — too flat clogs, too steep erodes.","Manholes, lift stations, and force mains navigate terrain and depth.","Capacity design uses peaking factors for the worst hour, not the average."],"examples":["A lift station's pumps kicking on during the morning shower peak.","A cured-in-place liner renewing a century-old brick sewer without digging."],"history":["19th-century combined sewers cleaned cities but pollute rivers in storms.","The 2000s-10s brought green infrastructure to reduce combined overflows."],"uses":["Cities map, model, and rehabilitate sewer networks continuously.","Engineers design separations and storage tunnels for overflow control.","Developers connect new projects under capacity permits."],"qa":[["What is a CSO?","Combined sewer overflow — diluted sewage released in heavy rain."],["Can sewers be trenchless-renewed?","Yes — lining and pipe-bursting avoid open-cut chaos."],["Why do basements back up?","Surcharged sewers or blocked laterals — backwater valves protect homes."]]},{"title":"Stormwater Management","brief":"Taming urban runoff — the floods, erosion, and pollution that pavement creates.","points":["Impervious surfaces multiply runoff volume and speed dramatically.","Detention ponds shave flood peaks; retention ponds also improve quality.","Low-impact development mimics nature with swales, rain gardens, and permeable pavement.","MS4 permits require cities to manage stormwater quality, not just quantity."],"examples":["A rain garden capturing a parking lot's first flush.","A regional detention basin filling during a cloudburst, sparing downstream homes."],"history":["1970s flood control meant concrete channels; the 1990s-2000s rediscovered green approaches.","MS4 stormwater permits (1990s+) forced cities to treat runoff quality."],"uses":["Engineers size ponds, pipes, and green infrastructure for developments.","Cities retrofit watersheds to meet TMDL pollutant limits.","Floodplain managers map risk and buy out the most vulnerable properties."],"qa":[["What is the first flush?","The dirtiest initial runoff carrying accumulated oils and metals."],["Do rain gardens work?","Yes — they cut volume and filter pollutants effectively."],["Who pays?","Stormwater utilities increasingly fund systems with dedicated fees."]]},{"title":"Green Infrastructure","brief":"Using soils, plants, and natural processes as engineered stormwater and climate systems.","points":["Bioswales, rain gardens, green roofs, and permeable pavement manage water at its source.","Urban trees intercept rain, cool streets, and filter air — quantified in dollars.","Constructed wetlands polish stormwater and wastewater naturally.","Maintenance determines success — green systems are living infrastructure."],"examples":["A downtown green street's planters drinking the block's runoff.","A green roof's meadow thriving five stories above traffic."],"history":["1970s experiments (like Seattle's SEA Streets, 2001) proved the concept.","The 2010s made green infrastructure standard practice in progressive cities."],"uses":["Cities write green infrastructure into codes and capital plans.","Landscape architects and engineers co-design living systems.","Researchers quantify performance to justify investment."],"qa":[["Is it cheaper than pipes?","Often, especially counting co-benefits like cooling and beauty."],["Does it work in winter?","With proper design for freeze-thaw — yes, though infiltration slows."],["Who maintains it?","The critical question — successful programs fund maintenance explicitly."]]},{"title":"Erosion and Sediment Control","brief":"Keeping soil on construction sites out of streams — silt fences, basins, and good timing.","points":["Sediment is the top construction pollutant — it smothers streambeds and carries nutrients.","Perimeter controls (silt fence, wattles) trap sediment at the boundary.","Sediment basins settle runoff before discharge; inlet protection guards storm drains.","Phasing and stabilization — covering soil fast — beat any trap."],"examples":["A silt fence bowing under muddy water after a thunderstorm.","Hydroseeded slopes greening within weeks of grading."],"history":["1970s-90s stormwater rules made erosion control a permit requirement.","The 2000s brought turbidity limits and active treatment on big sites."],"uses":["Inspectors check sites weekly and after every rain.","Contractors install and maintain BMPs as grading proceeds.","Designers minimize disturbed area and keep buffers along streams."],"qa":[["Do silt fences work?","When trenched in and maintained — most failures are installation and neglect."],["What is a SWPPP?","Stormwater Pollution Prevention Plan — the site's legally required playbook."],["Can you build in the rain?","Grading in wet seasons multiplies risk — schedule and stabilize accordingly."]]},{"title":"Environmental Hydraulics","brief":"The fluid mechanics behind treatment plants, rivers, and outfalls — open channels, weirs, and mixing.","points":["Open-channel hydraulics (Manning's equation) sizes sewers, channels, and spillways.","Weirs and flumes measure flow accurately for compliance and billing.","Mixing-zone analysis predicts how discharges dilute in rivers.","CFD modeling optimizes tank hydraulics before concrete is poured."],"examples":["A Parshall flume's throat precisely metering plant effluent.","A CFD model revealing dead zones in a chlorine contact tank."],"history":["19th-century hydraulic formulas still underpin modern design.","The 1990s-2000s brought CFD into everyday environmental design."],"uses":["Engineers verify every treatment unit's hydraulics before building.","Flood modelers predict water-surface profiles for mapping.","Outfall designers prove discharges meet water-quality standards."],"qa":[["What is head loss?","Energy lost to friction — the pump's enemy and the designer's constraint."],["Why does mixing matter?","Poor mixing wastes chemicals and lets pathogens survive disinfection."],["Can models replace testing?","They guide design; dye studies and field data still validate."]]},{"title":"Hydrology for Engineers","brief":"Predicting how much water arrives, when — the foundation of every water project.","points":["The hydrologic cycle: precipitation, infiltration, runoff, evapotranspiration.","Unit hydrographs and rational methods estimate flood peaks from watersheds.","Frequency analysis turns stream-gauge records into 100-year flood estimates.","Continuous simulation models decades of rainfall for water-supply planning."],"examples":["A HEC-HMS model predicting a subdivision's runoff increase.","A flood-frequency curve setting a bridge's design elevation."],"history":["1930s-50s unit-hydrograph theory built modern flood hydrology.","NOAA Atlas 14 (2000s-10s) updated rainfall statistics nationwide."],"uses":["Engineers size culverts, dams, and detention from hydrologic analysis.","Water suppliers plan reservoirs against drought hydrology.","Climate change is forcing updates to 'stationary' rainfall statistics."],"qa":[["What is time of concentration?","How long water takes to cross the watershed — key to peak-flow timing."],["Why do floods surprise us?","Short records and changing land use make statistics uncertain."],["Is rainfall really increasing?","Intensity is rising in most regions — design standards are catching up."]]},{"title":"Water Reuse and Recycling","brief":"Treating wastewater to drinking or irrigation standards — the drought-proof water supply.","points":["Non-potable reuse irrigates landscapes, golf courses, and industry.","Indirect potable reuse recharges aquifers or reservoirs with advanced-treated water.","Direct potable reuse — 'toilet to tap' — uses full advanced treatment trains.","Multiple barriers (membranes, UV, advanced oxidation) make reuse safe."],"examples":["Orange County's groundwater replenishment system — the world's largest potable reuse.","A city's purple-pipe network irrigating parks with recycled water."],"history":["1960s-70s experiments proved the concept; 2000s droughts made it mainstream.","Singapore's NEWater (2003) showed the public accepts high-tech reuse."],"uses":["Water-scarce cities build reuse into long-term supply portfolios.","Engineers design advanced treatment trains for potable standards.","Regulators are writing direct-potable-reuse rules now."],"qa":[["Is recycled water safe?","Advanced-treated reuse water meets or beats conventional drinking water."],["Why the 'yuck factor'?","Psychology, not science — education and transparency overcome it."],["Is it expensive?","Often cheaper than desalination or importing distant water."]]},{"title":"Desalination","brief":"Making seawater drinkable — membranes and heat turning oceans into taps.","points":["Reverse osmosis pushes seawater through membranes at 800+ psi, rejecting salt.","Thermal distillation boils and condenses — energy-hungry but robust.","Energy recovery devices cut RO energy dramatically — now ~3 kWh per cubic meter.","Brine disposal is the environmental challenge — dense, salty concentrate."],"examples":["A coastal RO plant's membrane racks humming at high pressure.","A ship's watermaker producing fresh water from the sea."],"history":["1960s-70s thermal plants served the Gulf states; RO took over in the 1990s-2000s.","Israel's Sorek (2013) proved large-scale desalination affordable."],"uses":["Arid coastal cities build desalination for drought-proof supply.","Engineers optimize intake design to protect marine life.","Industry desalinates brackish water inland too."],"qa":[["Why not desalinate everywhere?","Energy cost and brine — it's the supply of last resort inland."],["Is desalinated water healthy?","Yes — minerals are re-added for taste and pipe protection."],["What about the brine?","Diffuser outfalls dilute it; zero-liquid-discharge is emerging."]]},{"title":"Membrane Filtration Technologies","brief":"Microscopic sieves — microfiltration to reverse osmosis — redefining water treatment.","points":["Pore sizes step down: MF (0.1 micron), UF (0.01), NF (0.001), RO (0.0001).","Membranes physically remove pathogens — a true barrier, not just chemistry.","Fouling is the operating battle — managed with backwashing and cleaning.","MBRs (membrane bioreactors) pack treatment into a fraction of the footprint."],"examples":["An MBR plant's membrane cassettes producing crystal-clear effluent.","A home RO unit's compact cartridges under the sink."],"history":["1980s-90s membranes entered municipal treatment; costs fell 10x by the 2010s.","The 2000s MBR boom let cities upgrade without buying land."],"uses":["Engineers retrofit plants with membranes for tight permits and small sites.","Industry uses membranes for process water and zero discharge.","Emergency responders deploy mobile membrane units."],"qa":[["Do membranes remove everything?","Pathogens and particles yes; dissolved salts need RO."],["How long do membranes last?","5-10 years with proper pretreatment and cleaning."],["Are they expensive?","Capital costs fell sharply; energy and replacement are the ongoing costs."]]},{"title":"Activated Sludge Process","brief":"The microbial workhorse of sewage treatment — billions of bacteria eating waste in aerated tanks.","points":["Aeration basins supply oxygen to mixed liquor — the brown microbial soup.","Secondary clarifiers settle the biomass; most is recycled, some wasted.","SRT (sludge age) controls the biology — longer ages nitrify ammonia.","Bulking and foaming are the classic operating headaches."],"examples":["An operator judging mixed liquor health by its chocolate-milk look and earthy smell.","Fine-bubble diffusers' rolling boil maximizing oxygen transfer."],"history":["Ardern and Lockett's 1914 Manchester experiments invented the process.","The 1970s-80s added nutrient removal to the basic design."],"uses":["Operators tune aeration, wasting, and recycle daily.","Engineers design basin volumes and aeration for permit limits.","Researchers develop granular sludge and other intensifications."],"qa":[["What does it smell like?","Healthy plants smell earthy; rotten-egg odors mean trouble."],["Why is aeration expensive?","Blowers are typically a plant's biggest energy user."],["Can it handle toxins?","Shock loads can kill the biology — equalization and pretreatment protect it."]]},{"title":"Anaerobic Digestion","brief":"Letting microbes work without oxygen — stabilizing sludge while making biogas energy.","points":["Anaerobes convert organics to methane and CO2 in sealed heated tanks.","Digestion cuts sludge volume in half and kills pathogens.","Biogas fuels combined heat-and-power engines or upgrades to pipeline gas.","Co-digestion adds food waste to boost gas production."],"examples":["A digester's floating cover rising and falling with gas production.","A bus fleet running on biomethane from sewage sludge."],"history":["1890s Exeter, England: one of the first sewage digesters with gas use.","The 2000s-10s energy boom made digestion a revenue center."],"uses":["Treatment plants digest sludge to cut disposal costs and make power.","Farms digest manure, controlling odor and making fertilizer.","Food processors digest waste instead of paying to haul it."],"qa":[["Does it smell?","Well-run digesters are sealed — far less odor than raw sludge."],["What is digestate?","The stabilized residue — a useful soil amendment."],["Can it explode?","Methane is handled with gas safety systems like any fuel gas."]]},{"title":"Nutrient Removal Systems","brief":"Stripping nitrogen and phosphorus from wastewater to stop downstream dead zones.","points":["Nitrification converts ammonia to nitrate; denitrification converts nitrate to nitrogen gas.","Biological phosphorus removal uses cycling anaerobic/aerobic zones.","Chemical precipitation with alum or ferric backs up biological removal.","Limits as low as 3 mg/L nitrogen and 0.1 mg/L phosphorus are now common."],"examples":["An oxidation ditch's alternating zones visibly shifting microbial activity.","A filter's effluent testing under 0.1 mg/L phosphorus."],"history":["1970s-80s research cracked the microbiology of nutrient removal.","Chesapeake Bay and Great Lakes programs drove 1990s-2000s upgrades."],"uses":["Engineers retrofit plants with anoxic zones and chemical feed.","Operators manage carbon dosing and recycle rates daily.","Watershed groups track progress toward TMDL goals."],"qa":[["Why remove nutrients?","They feed algal blooms and dead zones downstream."],["Is it expensive?","Capital-intensive but transformative for receiving waters."],["Can nutrients be recovered?","Yes — struvite recovery turns phosphorus into fertilizer."]]},{"title":"Industrial Wastewater Pretreatment","brief":"Stopping factory pollutants at the source before they hit municipal plants or rivers.","points":["Categorical standards set national limits by industry type.","Equalization tanks smooth shock loads that would kill treatment biology.","Oil-water separators, DAF units, and chemical precipitation handle common wastes.","POTWs permit and inspect significant industrial users."],"examples":["A DAF unit's froth skimming oils off a food plant's wastewater.","A metal finisher's precipitation system dropping chrome from rinse water."],"history":["The 1972 Clean Water Act created the pretreatment program.","1980s categorical standards targeted electroplaters, metal finishers, and more."],"uses":["Industries design pretreatment to meet local limits.","POTW inspectors sample and enforce permits.","Consultants troubleshoot when surcharges spike."],"qa":[["What is a surcharge?","Extra fees when waste exceeds normal strength."],["Can industry discharge directly?","Yes, with its own NPDES permit and full treatment."],["What kills POTW biology?","Metals, solvents, extreme pH, and slug loads."]]},{"title":"Air Emission Inventories","brief":"Counting every ton of pollution — the accounting behind air-quality plans.","points":["Point sources (stacks), area sources (dry cleaners), mobile, and biogenic all count.","Emission factors estimate pollution from activity data like fuel burned.","Inventories feed photochemical models that test control strategies.","Triennial national inventories anchor state implementation plans."],"examples":["A state's inventory showing mobile sources dominate NOx.","A refinery's fenceline data reconciling with reported emissions."],"history":["1970s inventories were crude; the 1990s brought systematic national methods.","Satellites now independently check reported emissions."],"uses":["States build inventories for EPA approval of clean-air plans.","Modelers test 'what-if' controls before regulators commit.","Citizens use TRI data to see local releases."],"qa":[["What is the TRI?","Toxics Release Inventory — public data on industrial chemical releases."],["How accurate are inventories?","Point sources good; area and mobile sources more uncertain."],["Do satellites agree?","Increasingly they check and correct official numbers."]]},{"title":"Stack Design and Dispersion Modeling","brief":"Getting exhaust up, diluted, and compliant — plume physics in practice.","points":["Taller stacks and higher velocity improve dispersion — within GEP limits.","AERMOD is the EPA workhorse model for near-field dispersion.","Building downwash can trap plumes — modeled explicitly.","Fenceline concentrations must meet standards at the worst receptor."],"examples":["A modeler's isopleth map showing compliance at the property line.","A stack's sampling ports where testers verify emissions."],"history":["1950s-60s plume-rise formulas; AERMOD replaced ISC in 2005.","Good-engineering-practice stack height rules curbed 'tall-stack' cheating."],"uses":["Engineers model every major permit application.","Consultants defend permits against challenges.","Regulators review modeling for protectiveness."],"qa":[["Can a taller stack solve everything?","No — GEP limits prevent dispersion-as-dilution abuse."],["What is building downwash?","Wakes behind buildings pulling plumes to the ground."],["How are models validated?","Against tracer studies and ambient monitoring."]]},{"title":"Baghouses and Electrostatic Precipitators","brief":"The two giants of industrial dust control — filters versus electric fields.","points":["Baghouses pulse-clean fabric filters, hitting 99.9%+ on fine particles.","ESPs charge particles and collect them on grounded plates — no filter to replace.","Baghouses handle variable dust better; ESPs suit huge hot gas volumes.","Hopper evacuation and ash handling complete both systems."],"examples":["A baghouse's timed pulse-jets thumping bags clean.","An ESP's rappers knocking collected dust into hoppers."],"history":["ESPs (1907, Cottrell) cleaned smelters; baghouses scaled up in the 1970s.","Mercury and PM2.5 rules (2000s-10s) pushed both to higher performance."],"uses":["Power plants, cement kilns, and smelters depend on these workhorses.","Engineers select based on dust properties and gas conditions.","Operators watch pressure drop and opacity for performance."],"qa":[["Which is better?","Depends — baghouses win on efficiency, ESPs on operating cost for big flows."],["What breaks bags?","Heat, moisture, abrasion, and chemical attack."],["Do they catch mercury?","With activated-carbon injection ahead of them, substantially."]]},{"title":"Scrubbers for Gas Control","brief":"Washing acid gases out of exhaust — wet chemistry at industrial scale.","points":["Wet scrubbers spray alkaline slurry to absorb SO2, HCl, and HF.","Limestone forced-oxidation systems make wallboard-grade gypsum byproduct.","Venturi scrubbers capture fine particles with high-energy contacting.","Dry and semi-dry systems suit smaller sources and water-limited sites."],"examples":["A power-plant absorber tower's mist eliminators dripping clean.","A gypsum conveyor carrying scrubber byproduct to wallboard plants."],"history":["1970s acid-rain controls made scrubbers standard on coal plants.","The 1990 Clean Air Act amendments drove the big retrofit wave."],"uses":["Utilities operate scrubbers as part of generation.","Engineers design for removal efficiency and byproduct value.","Inspectors verify continuous emission monitors' data."],"qa":[["What happens to the sludge?","Oxidized to gypsum — sold, not landfilled, when markets exist."],["Do scrubbers waste water?","They consume water; zero-liquid-discharge designs recycle it."],["Can they capture CO2?","Amine scrubbing does — the leading post-combustion carbon-capture method."]]},{"title":"Catalytic Air Pollution Control","brief":"Using catalysts to destroy pollutants at lower temperatures — SCR, oxidation catalysts, and more.","points":["SCR injects ammonia/urea over catalyst to convert NOx to nitrogen and water.","Oxidation catalysts burn CO and VOCs at a few hundred degrees.","Three-way catalysts on cars handle NOx, CO, and HC simultaneously.","Catalyst poisoning by sulfur or metals is the operating enemy."],"examples":["A gas turbine's SCR system silently meeting single-digit NOx ppm.","A paint booth's oxidizer destroying solvent fumes for heat recovery."],"history":["1970s automotive catalysts; 1980s-90s SCR on power plants.","2010s diesel SCR (DEF systems) cleaned up trucks."],"uses":["Engineers size catalyst volume for the required destruction efficiency.","Operators manage ammonia slip and catalyst replacement cycles.","Regulators rely on catalysts for the tightest NOx limits."],"qa":[["What is ammonia slip?","Excess reagent passing through — itself regulated."],["How long do catalysts last?","Years; deactivation is gradual and monitored."],["Do they work cold?","Poorly — light-off temperature is the key design parameter."]]},{"title":"Indoor Air Quality Engineering","brief":"Designing buildings that breathe clean — ventilation, filtration, and source control.","points":["ASHRAE 62.1 sets ventilation rates per person and per floor area.","MERV-13+ filtration captures respiratory aerosols and fine particles.","Demand-controlled ventilation uses CO2 sensors to ventilate smartly.","Source control — low-VOC materials — beats dilution every time."],"examples":["A school's CO2-controlled ventilators ramping up as classes fill.","A hospital's HEPA-filtered isolation rooms protecting patients."],"history":["1970s energy crisis cut ventilation and created sick buildings.","ASHRAE standards and the 2020s pandemic rebuilt ventilation priorities."],"uses":["Mechanical engineers design HVAC for health and efficiency.","Commissioning agents verify systems perform as designed.","Building owners earn wellness certifications (WELL, Fitwel)."],"qa":[["How much ventilation is enough?","Follow ASHRAE 62.1 — roughly 15-20 cfm per person in offices."],["Do portable purifiers help?","Yes — properly sized HEPA units cut particles substantially."],["What about humidity?","Keep 40-60% — too dry spreads viruses, too damp grows mold."]]},{"title":"Noise Control Engineering","brief":"Designing quieter machines, barriers, and buildings — acoustics as engineering.","points":["Source-path-receiver: quiet the source, block the path, or protect the receiver.","Barriers work by breaking line-of-sight; mass and height determine insertion loss.","Enclosures and silencers tame industrial equipment noise.","Room acoustics balance absorption and reflection for the use."],"examples":["A highway barrier's 8-dB cut making backyards livable.","A compressor enclosure dropping plant-boundary noise to compliance."],"history":["1970s noise regulations professionalized the field.","Modern modeling (CadnaA, SoundPLAN) predicts before building."],"uses":["Engineers model and mitigate for permits and lawsuits.","Architects design studios, hospitals, and schools for quiet.","Product designers quiet appliances and vehicles."],"qa":[["How much does a barrier help?","5-10 dB typically — perceived as halving loudness."],["What is STC?","Sound Transmission Class — higher means better wall soundproofing."],["Can noise be eliminated?","Reduced greatly, rarely eliminated — physics sets limits."]]},{"title":"Environmental Monitoring System Design","brief":"Architecting the networks that watch air, water, and soil continuously.","points":["Design starts with objectives — compliance, alerts, or research — then picks parameters.","Station siting follows strict rules; a bad location ruins good instruments.","Telemetry (cellular, satellite) delivers data in real time.","QA/QC — calibrations, audits, data validation — makes data defensible."],"examples":["A fenceline network texting alerts when benzene spikes.","A buoy array reporting reservoir water quality every 15 minutes."],"history":["1970s compliance monitoring built the first networks.","The 2010s IoT wave added dense low-cost layers."],"uses":["Consultants design networks for industry and agencies.","Data managers validate and publish continuous data.","Responders rely on real-time feeds during incidents."],"qa":[["How many stations are enough?","Enough to capture gradients — modeling guides placement."],["What breaks monitors?","Power, communications, fouling, and calibration drift."],["Who sees the data?","Increasingly everyone — public dashboards are the norm."]]},{"title":"Sampling Design and Statistics","brief":"Getting representative samples — because bad sampling ruins the best lab work.","points":["DQO (data quality objectives) process links decisions to sampling effort.","Random, stratified, and systematic designs each suit different questions.","Composite samples average variability; grabs catch peaks.","Statistics — confidence intervals, hypothesis tests — turn data into decisions."],"examples":["A stratified soil-sampling plan cutting a site's analytical bill in half.","A composite sampler catching a plant's daily average discharge."],"history":["1980s-90s EPA guidance formalized environmental statistics.","The 2000s brought user-friendly software (ProUCL) to practitioners."],"uses":["Consultants design sampling plans that survive regulatory review.","Labs flag QC failures that invalidate results.","Attorneys attack or defend cases on sampling statistics."],"qa":[["How many samples?","Enough for statistical confidence — power analysis says how many."],["Grab or composite?","Grabs for peaks and compliance; composites for averages."],["What is a duplicate?","A second sample checking precision — required QA."]]},{"title":"Environmental Risk Assessment","brief":"Quantifying the odds and severity of harm — the science behind cleanup and safety decisions.","points":["Four steps: hazard ID, dose-response, exposure assessment, risk characterization.","Cancer risk targets (1 in a million to 1 in 10,000) drive many cleanups.","Exposure models track chemicals from source to people via air, water, food, soil.","Uncertainty analysis keeps assessments honest about what isn't known."],"examples":["A risk assessment setting a site's soil cleanup levels.","A chemical's reference dose protecting sensitive subpopulations."],"history":["1983 EPA 'Red Book' founded the risk-assessment paradigm.","The 1990s-2000s refined probabilistic methods."],"uses":["Consultants prepare risk assessments for cleanups and permits.","Regulators use them to set standards and approve remedies.","Industry uses them to prioritize product-safety work."],"qa":[["Is 1-in-a-million risk real?","It's a policy target — modeling, not body counts."],["Who is most vulnerable?","Children, pregnant women, the elderly — assessments protect them explicitly."],["Risk vs hazard?","Hazard is potential; risk includes exposure — the dose makes the poison."]]},{"title":"Environmental Regulations and Permitting","brief":"Navigating the laws that govern pollution — permits as the operating license to exist.","points":["Major US laws: Clean Air Act, Clean Water Act, RCRA, CERCLA, NEPA, TSCA.","Permits translate laws into facility-specific limits and monitoring.","Title V air permits consolidate every requirement into one document.","Noncompliance brings notices, fines, and citizen suits."],"examples":["A factory's Title V permit — hundreds of pages of limits and monitoring.","A developer's wetland permit with mitigation conditions."],"history":["1970s laws built the system; 1980s-90s strengthened enforcement.","The 2020s added PFAS, environmental justice, and climate disclosure."],"uses":["Environmental managers keep facilities in compliance daily.","Consultants prepare permit applications and negotiate terms.","Attorneys defend enforcement actions and citizen suits."],"qa":[["How long do permits take?","Months for simple; years for complex or controversial."],["What triggers a permit?","Emissions, discharges, waste handling, or land disturbance above thresholds."],["Can permits be challenged?","Yes — by applicants and by citizens, in administrative and court appeals."]]},{"title":"NEPA and Environmental Review","brief":"The look-before-you-leap law forcing federal actions to disclose environmental impacts.","points":["Categorical exclusions cover routine actions; EAs handle uncertain ones; EISs tackle the big ones.","Alternatives analysis — including no-action — is the heart of the review.","Public comment periods let anyone shape the analysis.","Mitigation commitments become binding conditions."],"examples":["A highway EIS comparing routes and their wetland impacts.","A solar project's EA with tribal and public consultation."],"history":["NEPA (1970) invented impact assessment; courts shaped it through the 1970s-80s.","2020s reforms aim to speed reviews without gutting analysis."],"uses":["Agencies prepare reviews for projects, permits, and plans.","Consultants write the technical analyses.","Citizens and tribes use the process to protect interests."],"qa":[["Does NEPA block projects?","Rarely — it forces disclosure and consideration, not particular outcomes."],["How long does an EIS take?","Often 2-5 years for major projects."],["Do states have their own?","Many do — 'little NEPAs' with similar requirements."]]},{"title":"Sustainability Engineering","brief":"Designing for the triple bottom line — engineering that meets needs without stealing from the future.","points":["Life-cycle thinking prevents shifting burdens from one medium to another.","Circular design keeps materials in use — designing for disassembly and reuse.","Decarbonization roadmaps sequence efficiency, electrification, and clean supply.","Metrics (carbon, water, waste) make sustainability manageable."],"examples":["A factory's waste-heat recovery paying back in two years.","A product redesigned for disassembly, doubling recycling value."],"history":["1987 Brundtland Report defined sustainable development.","The 2010s-20s made corporate sustainability a board-level discipline."],"uses":["Engineers lead corporate decarbonization and circularity programs.","Consultants verify claims and build ESG reports.","Investors screen on sustainability performance."],"qa":[["Is sustainability profitable?","Efficiency and waste reduction usually are; the business case is strong."],["What is Scope 3?","Supply-chain emissions — typically the biggest and hardest slice."],["Greenwashing?","Unverified claims invite lawsuits — measure, verify, disclose."]]},{"title":"Green Building Design","brief":"Engineering buildings that sip energy and water while keeping occupants healthy.","points":["High-performance envelopes — insulation, airtightness, right-sized windows — come first.","Efficient HVAC, heat recovery, and smart controls cut energy 30-50%.","Water-efficient fixtures, rainwater, and greywater cut potable demand.","LEED, ENERGY STAR, and Passive House certify performance."],"examples":["A Passive House's thick walls and heat-recovery ventilator.","A LEED Platinum office's daylighting and green roof."],"history":["1970s energy crisis sparked efficient design; LEED (2000) mainstreamed it.","The 2010s-20s pushed net-zero-energy buildings."],"uses":["Architects and engineers collaborate from the first sketch.","Commissioning agents verify performance in operation.","Owners earn certifications that command rent premiums."],"qa":[["Does green cost more?","2-5% upfront typically, repaid in energy and health."],["What is net-zero?","Producing as much energy yearly as consumed."],["Healthiest feature?","Ventilation and daylight — occupants notice immediately."]]},{"title":"Energy Efficiency in Treatment","brief":"Cutting the energy appetite of water and wastewater plants — often a city's biggest electricity user.","points":["Aeration blowers are the prime target — fine-bubble diffusers and DO control save 20-30%.","Pumps with VFDs match speed to demand instead of throttling valves.","Biogas from digestion offsets plant power; solar covers rooftops and basins.","Energy audits benchmark kWh per million gallons treated."],"examples":["A plant's turbo blowers cutting aeration energy by a quarter.","Floating solar panels shading a reservoir while making power."],"history":["1970s energy crises first targeted plant power bills.","The 2010s net-zero-energy plant movement proved it achievable."],"uses":["Utilities audit and retrofit for savings and resilience.","Engineers design efficiency into every upgrade.","Regulators increasingly reward energy performance."],"qa":[["Biggest energy hog?","Aeration in wastewater; pumping in water supply."],["Can plants be net-zero?","Yes — with biogas, solar, and efficiency combined."],["What is a VFD?","Variable-frequency drive — matches motor speed to need."]]},{"title":"Carbon Capture Engineering","brief":"Stripping CO2 from smokestacks and air — the backstop technology for hard-to-abate emissions.","points":["Post-combustion amine scrubbing is the most mature capture method.","Oxy-fuel and pre-combustion designs capture from redesigned processes.","Direct air capture pulls CO2 from ambient air at higher cost.","Storage in deep saline formations or basalt must be permanent and monitored."],"examples":["A cement plant's pilot capture unit compressing CO2 for storage.","A DAC facility's giant fans filtering the sky."],"history":["1970s natural-gas processing pioneered CO2 separation.","The 2010s-20s scaled pilots toward commercial deployment."],"uses":["Engineers integrate capture with power and industrial plants.","Geologists characterize and monitor storage reservoirs.","Policymakers design 45Q credits and storage regulations."],"qa":[["Does it work?","Technically yes; economically it needs policy support."],["Where does the CO2 go?","Deep geological storage — or utilization in products and fuels."],["Is it an excuse to pollute?","Critics say so; proponents call it essential for cement, steel, and gas."]]},{"title":"Waste-to-Energy","brief":"Burning what can't be recycled to make power — volume reduction plus energy recovery.","points":["Mass-burn plants combust mixed waste, raising steam for power.","Air pollution controls (baghouses, scrubbers, SCR) make modern plants clean.","Ash is tested and used or landfilled; metals are recovered.","Europe leads; the US has ~75 plants, mostly in the Northeast."],"examples":["A plant's turbine powered by 2,000 tons of daily trash.","A district-heating network fed by waste combustion."],"history":["1980s US plants faced dioxin fears; 1990s MACT rules cleaned them up.","The 2000s-10s European model paired high recycling with WTE for residuals."],"uses":["Cities choose WTE where landfill space is scarce.","Engineers design for emissions compliance and energy efficiency.","Operators manage combustion for complete burnout."],"qa":[["Is it better than landfilling?","For residuals after recycling, usually yes — less methane, plus power."],["Does it discourage recycling?","Well-run systems do both — WTE handles what recycling can't."],["What about emissions?","Modern plants meet strict standards; monitoring is continuous."]]},{"title":"Composting Systems","brief":"Engineering controlled decomposition — turning organics into soil gold at scale.","points":["Aerated static piles and in-vessel systems compost faster than windrows.","Carbon-nitrogen ratio (~30:1), moisture, and oxygen control the process.","Pathogen kill requires sustained 131 F+ temperatures.","Odor control — biofilters, covers — determines neighbor relations."],"examples":["A facility's aerated bays turning food scraps into compost in weeks.","A city's curbside organics truck feeding the compost operation."],"history":["1970s backyard bins; 1990s-2000s municipal yard-waste programs.","The 2010s-20s food-scrap diversion boom built large facilities."],"uses":["Cities divert organics to meet landfill bans and climate goals.","Engineers design aeration, drainage, and odor control.","Farmers buy the finished compost for soil health."],"qa":[["What can be composted?","Food scraps, yard waste, soiled paper — not plastics or glass."],["Does it smell?","Well-run facilities manage odor; poor ones don't."],["Is composting better than landfilling organics?","Dramatically — it avoids landfill methane."]]},{"title":"Recycling Systems Design","brief":"Designing the collection-to-market chain that turns discards back into feedstock.","points":["Single-stream is convenient but contaminates; dual-stream is cleaner.","MRF design sequences screens, magnets, eddy currents, and optical sorters.","End markets determine what gets recycled — design for demand, not just diversion.","Contamination rates make or break program economics."],"examples":["An optical sorter's air jets flicking plastics by polymer type.","A glass cleanup line turning mixed cullet into furnace-ready feed."],"history":["1990s curbside boom; 2018 China's National Sword forced quality reform.","The 2020s rebuild domestic processing and demand."],"uses":["Cities redesign programs for cleaner streams and stable markets.","Engineers build MRFs around commodity realities.","Brands design packaging for actual recyclability."],"qa":[["What is wishcycling?","Tossing non-recyclables in hope — it contaminates good material."],["Why did recycling struggle?","China's import ban exposed dependence on cheap export markets."],["What actually gets recycled?","Cardboard, metals, PET and HDPE bottles — reliably."]]},{"title":"Brownfield Redevelopment Engineering","brief":"Returning contaminated sites to productive use — engineering plus deal-making.","points":["Phase I/II assessments define the liability picture before purchase.","Risk-based cleanups match remedy to future use — not to pristine.","Engineering controls (caps, vapor barriers) manage residual risk.","Liability protections and tax incentives make deals pencil out."],"examples":["A former factory reborn as apartments with a vapor barrier beneath.","A cleaned rail yard becoming a riverfront park."],"history":["1980s Superfund liability froze redevelopment; 2002 Brownfields Law thawed it.","The 2010s-20s turned brownfields into prime urban infill."],"uses":["Developers assemble assessment, cleanup, and financing packages.","Engineers design remedies that enable construction schedules.","Cities use brownfields for tax-base growth without sprawl."],"qa":[["Is it safe to live on?","With proper cleanup and controls, yes — regulators approve residential reuse."],["Who pays?","Mix of developers, grants, tax credits, and sometimes responsible parties."],["How long does it take?","1-3 years typically for assessment through cleanup."]]},{"title":"Mine Reclamation Engineering","brief":"Healing mined land — regrading, revegetating, and treating acid drainage.","points":["Reclamation plans precede mining under modern law — bonds guarantee performance.","Acid mine drainage (AMD) needs perpetual treatment or source control.","Revegetation uses native species matched to reconstructed soils.","Pit lakes and highwalls pose long-term safety and water challenges."],"examples":["A regraded mountaintop mine returning as hardwood forest.","A limestone channel neutralizing AMD before it reaches a trout stream."],"history":["1977 SMCRA mandated coal-mine reclamation in the US.","The 2000s-10s tackled legacy hardrock mines' perpetual drainage."],"uses":["Mining companies reclaim progressively during operations.","Engineers design AMD treatment for decades of operation.","Agencies oversee bond release when reclamation succeeds."],"qa":[["Can mines be fully restored?","Function can return; original ecosystems take centuries if ever."],["What is AMD?","Sulfuric acid from exposed pyrite — the legacy pollutant of mining."],["Who pays for abandoned mines?","Taxpayers, mostly — the Superfund and state programs."]]},{"title":"Constructed Wetlands","brief":"Building marshes that treat wastewater and stormwater — ecology as infrastructure.","points":["Plants, microbes, and soils filter pollutants as water flows through.","Surface-flow wetlands suit polishing; subsurface-flow handles stronger waste.","Design sizes area and detention for target removal rates.","Wildlife habitat and beauty are free co-benefits."],"examples":["A treatment wetland's cattails polishing effluent to stream quality.","A stormwater wetland's forebay trapping sediment before the marsh."],"history":["1970s experiments (like Arcata, California) proved municipal-scale treatment.","The 1990s-2000s standardized design for nutrients and metals."],"uses":["Small towns use wetlands for affordable advanced treatment.","Engineers design for cold climates with subsurface flow.","Industry polishes effluent and manages stormwater with wetlands."],"qa":[["Do they smell?","Well-designed subsurface wetlands don't — avoid stagnant surface designs."],["What about mosquitoes?","Design for flow and predators; poor designs do breed them."],["How well do they work?","Excellent for BOD, solids, and nutrients at modest loadings."]]},{"title":"Phytoremediation","brief":"Using plants to extract, degrade, or stabilize contaminants — solar-powered cleanup.","points":["Phytoextraction accumulates metals in harvestable shoots.","Phytodegradation breaks down organics in the root zone.","Phytostabilization locks contaminants in place with roots.","It's slow and shallow — best for large, low-level sites."],"examples":["Sunflowers pulling lead from an urban lot's soil.","Poplars' deep roots intercepting a shallow solvent plume."],"history":["1990s research proved hyperaccumulators' metal uptake.","The 2000s-10s refined it for brownfields and mine sites."],"uses":["Site owners use it for low-cost polishing of large areas.","Researchers breed and engineer better remediating plants.","Communities accept green cleanup over heavy equipment."],"qa":[["How long does it take?","Years to decades — patience is the price of low cost."],["What happens to the plants?","Harvested and treated as waste if they hold metals."],["Does it really work?","For suitable sites and contaminants, peer-reviewed yes."]]},{"title":"Bioremediation Engineering","brief":"Engineering microbial cleanup — feeding the right bugs to eat pollution.","points":["Biostimulation adds nutrients/oxygen; bioaugmentation adds cultured microbes.","Aerobic bugs eat petroleum fast; anaerobes handle chlorinated solvents.","Treatability studies prove the biology works before full-scale spending.","Monitoring proves contaminant destruction, not just dilution."],"examples":["Injection wells feeding lactate to solvent-eating Dehalococcoides.","A biopile's blowers keeping petroleum-eating microbes oxygenated."],"history":["1980s Exxon Valdez bioremediation proved large-scale viability.","The 2000s Dehalococcoides discovery unlocked chlorinated-solvent cleanup."],"uses":["Engineers design injection layouts and amendment doses.","Labs culture and verify microbial communities.","Regulators accept bioremediation with performance monitoring."],"qa":[["Which contaminants?","Petroleum, solvents, some pesticides and explosives."],["How do you know it's working?","Daughter products, isotope shifts, and microbial counts."],["Can it fail?","Yes — wrong conditions or competing microbes; pilot-test first."]]},{"title":"Sediment Remediation","brief":"Cleaning contaminated mud — dredging it up, capping it in place, or letting nature bury it.","points":["Dredging removes contaminated sediment but resuspends some during the work.","Capping isolates contamination under clean sand or engineered layers.","Monitored natural recovery relies on clean sediment burying the old.","Residuals management decides success — the last 10 percent is the hardest."],"examples":["A harbor dredge's bucket closing on PCB-laden mud.","A sand cap's survey showing it intact after a decade."],"history":["1970s-80s Superfund sites forced sediment cleanup innovation.","The 2000s Hudson River dredging project was the largest ever."],"uses":["Engineers design dredge prisms and cap thicknesses.","Dredgers execute with GPS-guided precision.","Long-term monitoring verifies caps and recovery."],"qa":[["Dredge or cap?","Dredge for hotspots and navigation; cap for widespread low-level areas."],["Does dredging spread it?","Some resuspension is inevitable — silt curtains and BMPs limit it."],["How clean is clean?","Risk-based sediment quality objectives, not zero."]]},{"title":"Vapor Intrusion Mitigation","brief":"Keeping subsurface chemical vapors out of buildings — barriers, venting, and monitoring.","points":["Sub-slab depressurization — like radon mitigation — is the workhorse solution.","Vapor barriers under new slabs block entry from the start.","Indoor-air sampling verifies mitigation works.","Preferential pathways (sewers, sumps) can bypass barriers — investigate them."],"examples":["A depressurization fan quietly protecting a daycare over a solvent plume.","A new warehouse's vapor barrier going down before the slab pour."],"history":["2000s EPA vapor-intrusion guidance created the practice.","The 2010s brought standardized investigation and mitigation design."],"uses":["Engineers design mitigation for existing and new buildings.","Mitigators install and verify systems.","Regulators require VI assessment at contaminated sites."],"qa":[["How do vapors get in?","Through cracks, sumps, and utility penetrations — pressure drives them."],["Is it like radon?","Very — same physics, same mitigation approach."],["Can I test my building?","Yes — sub-slab and indoor-air sampling by qualified firms."]]},{"title":"Climate Adaptation Engineering","brief":"Designing infrastructure for the climate that's coming, not the one that was.","points":["Design standards are shifting from historical to projected rainfall and heat.","Flood adaptation: elevation, barriers, green infrastructure, managed retreat.","Heat adaptation: cool materials, shade, and resilient power for cooling.","Water-supply adaptation: diversification, reuse, and demand management."],"examples":["A coastal city's raised substations surviving the next hurricane.","A hospital's microgrid keeping cooling on through a heat-wave blackout."],"history":["Post-Katrina (2005) and Sandy (2012) rebuilds pioneered resilient design.","The 2020s made climate-adjusted design standard practice."],"uses":["Engineers climate-proof infrastructure designs.","Cities write adaptation into codes and capital plans.","Insurers price the residual risk."],"qa":[["Adapt or mitigate?","Both — mitigation slows warming; adaptation handles what's coming."],["What is managed retreat?","Strategically relocating from indefensible places."],["How do you design for uncertainty?","Flexible, staged, and robust designs over precise predictions."]]},{"title":"Environmental Nanotechnology","brief":"Engineering at the billionth-meter scale — nano-sorbents, catalysts, and sensors for cleanup.","points":["Nano zero-valent iron (nZVI) destroys chlorinated solvents in groundwater.","Nano-sorbents capture metals and PFAS with enormous surface areas.","Nano-sensors detect contaminants at previously impossible levels.","Fate and toxicity of nanoparticles themselves need assessment."],"examples":["nZVI injections collapsing a solvent plume's concentrations.","A nano-enabled sensor detecting lead at parts-per-trillion."],"history":["2000s: nZVI field trials proved nano-remediation.","The 2010s-20s expanded to PFAS sorbents and nano-sensors."],"uses":["Remediation firms deploy nano-iron for stubborn plumes.","Researchers develop targeted, recoverable nano-agents.","Regulators assess nanoparticle environmental safety."],"qa":[["Is nano-iron safe?","It oxidizes to ordinary iron; studies show low lasting risk."],["Why nano?","Surface area — a gram can have a football field of reactive surface."],["Commercial yet?","nZVI is commercial; many nano-sorbents are emerging."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-environmental-engineering-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('environmental-engineering',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();